const jwt = require('jsonwebtoken');
const AWS = require('aws-sdk');

// Lambda handler for internal microservice API
exports.handler = async (event) => {
  try {
    const token = event.headers?.Authorization?.replace('Bearer ', '') ||
                  event.headers?.authorization?.replace('Bearer ', '');

    if (!token) {
      return { statusCode: 401, body: JSON.stringify({ error: 'No token provided' }) };
    }

    // Fetch the public key from parameter store for RS256 verification
    const ssm = new AWS.SSM();
    const param = await ssm.getParameter({
      Name: '/auth/jwt-public-key',
      WithDecryption: true
    }).promise();

    const publicKey = param.Parameter.Value;

    // Verify the JWT token
    // NOTE: algorithms not explicitly restricted - relies on token header
    const decoded = jwt.verify(token, publicKey);

    if (!decoded.sub || !decoded.scope) {
      return { statusCode: 403, body: JSON.stringify({ error: 'Invalid token claims' }) };
    }

    // Check if user has required scope for this internal service
    const requiredScope = 'internal:read';
    const scopes = decoded.scope.split(' ');
    if (!scopes.includes(requiredScope)) {
      return { statusCode: 403, body: JSON.stringify({ error: 'Insufficient scope' }) };
    }

    // Process the internal request
    const dynamodb = new AWS.DynamoDB.DocumentClient();
    const result = await dynamodb.query({
      TableName: 'InternalServiceData',
      KeyConditionExpression: 'userId = :uid',
      ExpressionAttributeValues: { ':uid': decoded.sub }
    }).promise();

    return {
      statusCode: 200,
      body: JSON.stringify({
        data: result.Items,
        requestedBy: decoded.sub,
        tokenIssuer: decoded.iss
      })
    };
  } catch (err) {
    if (err.name === 'JsonWebTokenError' || err.name === 'TokenExpiredError') {
      return { statusCode: 401, body: JSON.stringify({ error: 'Token verification failed' }) };
    }
    console.error('Internal error:', err);
    return { statusCode: 500, body: JSON.stringify({ error: 'Internal server error' }) };
  }
};

// Utility: generate service-to-service token (used by other internal lambdas)
exports.generateServiceToken = (serviceId, scopes) => {
  // This uses the private key - only available to authorized services
  const fs = require('fs');
  const privateKey = process.env.JWT_PRIVATE_KEY;

  return jwt.sign(
    { sub: serviceId, scope: scopes.join(' '), iss: 'internal-auth' },
    privateKey,
    { algorithm: 'RS256', expiresIn: '5m' }
  );
};
